//! Chicago tests for `ggen_lsp::moniker` — real generated files on disk, real
//! kernel source, assertions on final state. No mocks.

use ggen_lsp::moniker::{
    identifier_at_position, is_generated_file, moniker_at_position, resolve_kernel_moniker,
    resolve_moniker_in_source, resolve_moniker_in_tree, Moniker,
};
use serde_json::json;
use std::fs;
use std::path::Path;

const BANNER: &str = "// Code generated by ggen. DO NOT EDIT.";

fn generated_commands_source() -> String {
    let mut s = String::from(BANNER);
    s.push_str(
        "\n// @generated — regenerating overwrites this file.\n\n\
         pub mod generated_commands {\n\
         \x20   pub const COMMANDS: [&str; 2] = [\"build\", \"sync\"];\n\
         \x20   pub fn run(cmd: &str) -> bool {\n\
         \x20       cmd == \"build\"\n\
         \x20   }\n\
         }\n",
    );
    s
}

fn write_file(root: &Path, rel: &str, source: &str) -> std::path::PathBuf {
    let p = root.join(rel);
    fs::create_dir_all(p.parent().unwrap()).unwrap();
    fs::write(&p, source).unwrap();
    p
}

#[test]
fn banner_detection_matches_both_spellings_and_rejects_non_generated() {
    assert!(is_generated_file(
        "// Code generated by ggen. DO NOT EDIT.\npub struct X;"
    ));
    assert!(is_generated_file(
        "// Auto-generated by ggen from wasm4pm-compat.ttl\npub enum Foo {}"
    ));
    assert!(!is_generated_file("pub mod ordinary { }"));
    // Banner only counts within the first BANNER_SCAN_LINES lines.
    let late = format!("{}\n{}", "\n".repeat(20), "// Code generated by ggen");
    assert!(!is_generated_file(&late));
}

#[test]
fn moniker_round_trips_through_display_and_parse() {
    let m = Moniker::new(
        "ggen-cli",
        vec!["generated_commands".into(), "COMMANDS".into()],
    );
    assert_eq!(m.to_string(), "ggen:ggen-cli:generated_commands::COMMANDS");
    let parsed = Moniker::parse("ggen:ggen-cli:generated_commands::COMMANDS").unwrap();
    assert_eq!(parsed, m);
    // Deterministic across repeated construction (stability across regeneration).
    let again = Moniker::new(
        "ggen-cli",
        vec!["generated_commands".into(), "COMMANDS".into()],
    );
    assert_eq!(m, again);
}

#[test]
fn parse_rejects_malformed_monikers() {
    assert!(Moniker::parse("notggen:cli:x").is_none());
    assert!(Moniker::parse("ggen::x").is_none()); // empty crate
    assert!(Moniker::parse("ggen:cli:").is_none()); // empty path
    assert!(Moniker::parse("ggen:cli:a:::b").is_some()); // tolerated: empty segment check
    assert!(Moniker::parse("ggen:cli:a::::b").is_none());
}

#[test]
fn moniker_at_position_resolves_module_scoped_const() {
    let source = generated_commands_source();
    // Line 4 (0-based): `    pub const COMMANDS: ...`, cursor inside COMMANDS.
    let m = moniker_at_position("ggen-cli", &source, 4, 20).expect("moniker on COMMANDS");
    assert_eq!(m.to_string(), "ggen:ggen-cli:generated_commands::COMMANDS");

    // Cursor inside `run` fn name resolves to the fn path.
    let m = moniker_at_position("ggen-cli", &source, 5, 13).expect("moniker on run");
    assert_eq!(m.to_string(), "ggen:ggen-cli:generated_commands::run");
}

#[test]
fn moniker_at_position_refuses_non_generated_and_off_symbol() {
    let source = generated_commands_source();
    assert!(moniker_at_position("ggen-cli", "pub mod x {}", 0, 7).is_none());
    // Off-word: position 1 sits between the two slashes of the banner comment.
    assert!(moniker_at_position("ggen-cli", &source, 0, 1).is_none());
    assert!(moniker_at_position("ggen-cli", &source, 2, 0).is_none()); // blank line
    assert!(moniker_at_position("ggen-cli", &source, 99, 0).is_none()); // out of range
}

#[test]
fn resolve_moniker_in_source_finds_decl_and_range() {
    let source = generated_commands_source();
    let m = Moniker::parse("ggen:ggen-cli:generated_commands::COMMANDS").unwrap();
    let range = resolve_moniker_in_source(&m, &source).expect("COMMANDS resolved");
    assert_eq!(range.start.line, 4);
    let line_text = source.lines().nth(4).unwrap();
    let slice: String =
        line_text[range.start.character as usize..range.end.character as usize].to_string();
    assert_eq!(slice, "COMMANDS");
    // Inverse-of-inverse: the resolved text re-derives the same moniker.
    let m2 =
        moniker_at_position("ggen-cli", &source, range.start.line, range.start.character).unwrap();
    assert_eq!(m, m2);
}

#[test]
fn resolve_moniker_in_tree_scans_only_generated_files_on_disk() {
    let dir = tempfile::tempdir().unwrap();
    write_file(
        dir.path(),
        "src/generated_commands.rs",
        &generated_commands_source(),
    );
    write_file(
        dir.path(),
        "src/handwritten.rs",
        "pub mod generated_commands {\n    pub const COMMANDS: &str = \"impostor\";\n}\n",
    );
    write_file(
        dir.path(),
        "src/other_generated.rs",
        &generated_commands_source(),
    );

    let m = Moniker::parse("ggen:ggen-cli:generated_commands::COMMANDS").unwrap();
    let hits = resolve_moniker_in_tree(&m, dir.path());
    assert_eq!(hits.len(), 2, "impostor (no banner) must not resolve");
    for h in &hits {
        let src = fs::read_to_string(&h.file).unwrap();
        assert!(is_generated_file(&src));
        let line: Vec<char> = src
            .lines()
            .nth(h.range.start.line as usize)
            .unwrap()
            .chars()
            .collect();
        let got: String = line[h.range.start.character as usize..h.range.end.character as usize]
            .iter()
            .collect();
        assert_eq!(got, "COMMANDS");
    }
    // Deterministic ordering by file path.
    let mut files: Vec<&std::path::PathBuf> = hits.iter().map(|h| &h.file).collect();
    files.sort();
    let sorted: Vec<&std::path::PathBuf> = hits.iter().map(|h| &h.file).collect();
    assert_eq!(files, sorted);
}

#[test]
fn resolve_moniker_misses_symbol_outside_declared_scope() {
    let source = generated_commands_source();
    let m = Moniker::parse("ggen:ggen-cli:other_module::COMMANDS").unwrap();
    assert!(resolve_moniker_in_source(&m, &source).is_none());
}

#[test]
fn kernel_moniker_resolves_against_real_abb_sbb_lib_rs() {
    let kernel_path = Path::new(env!("CARGO_MANIFEST_DIR")).join("../ggen-abb-sbb/src/lib.rs");
    let source = fs::read_to_string(&kernel_path)
        .expect("real kernel lib.rs must exist for the Chicago run");
    let m = Moniker::parse("ggen:abb-sbb:Refusal::SBB_MUTABLE").unwrap();
    let range = resolve_kernel_moniker(&m, &source).expect("SBB_MUTABLE variant resolved");
    // 0-based row of `#[error("SBB_MUTABLE: {sbb}")]` — the moniker id is the
    // variant's published error code, and the range covers the code token.
    assert_eq!(range.start.line, 249);
    let line_text = source.lines().nth(249).unwrap();
    let got: String =
        line_text[range.start.character as usize..range.end.character as usize].to_string();
    assert_eq!(got, "SBB_MUTABLE");
}

#[test]
fn kernel_moniker_rejects_wrong_shape_and_missing_variant() {
    let source = fs::read_to_string(
        Path::new(env!("CARGO_MANIFEST_DIR")).join("../ggen-abb-sbb/src/lib.rs"),
    )
    .unwrap();
    // Not an Enum::Variant shape.
    assert!(
        resolve_kernel_moniker(&Moniker::parse("ggen:abb-sbb:Refusal").unwrap(), &source).is_none()
    );
    // Three segments is outside the kernel shape.
    assert!(
        resolve_kernel_moniker(&Moniker::parse("ggen:abb-sbb:a::b::c").unwrap(), &source).is_none()
    );
    // Enum exists, variant does not.
    assert!(resolve_kernel_moniker(
        &Moniker::parse("ggen:abb-sbb:Refusal::NO_SUCH_VARIANT").unwrap(),
        &source
    )
    .is_none());
}

#[test]
fn identifier_at_position_handles_boundaries() {
    let src = "pub const COMMANDS: &str = \"x\";";
    assert_eq!(
        identifier_at_position(src, 0, 12).as_deref(),
        Some("COMMANDS")
    );
    assert_eq!(
        identifier_at_position(src, 0, 17).as_deref(),
        Some("COMMANDS")
    );
    assert_eq!(
        identifier_at_position(src, 0, 18).as_deref(),
        Some("COMMANDS")
    ); // cursor at word end
    assert_eq!(identifier_at_position(src, 0, 19), None); // on the colon
    assert_eq!(identifier_at_position(src, 5, 0), None); // out of range line
}

// Disclosure note: `identifier_at_position` one-past-end behavior asserts the
// LSP convention (cursor at word end still selects the word).

// ─────────────────────────────────────────────────────────────────────────────
// G4 fallback courts (wire-level, Chicago): the REAL spawned ggen-lsp binary
// resolves definition/references for generated surfaces whose analyzer is
// None. Resolution runs against the project root containing the file (ggen
// .toml walk-up), NOT the workspace root — witnessed by nesting the project
// (ggen.toml at proj/) inside a ggen.toml-free workspace root.
// ─────────────────────────────────────────────────────────────────────────────

mod wire {
    use serde_json::{json, Value};
    use std::io::{BufRead, BufReader, Write};
    use std::process::{Child, ChildStdin, Command, Stdio};
    use std::sync::mpsc::{self, Receiver};
    use std::thread;
    use std::time::Duration;
    use tempfile::TempDir;

    pub struct WireClient {
        stdin: ChildStdin,
        rx: Receiver<Value>,
        child: Child,
        _tmp: TempDir,
    }

    impl WireClient {
        pub fn spawn() -> Self {
            let bin = assert_cmd::cargo::cargo_bin("ggen-lsp");
            let tmp = TempDir::new().expect("tempdir");
            let mut child = Command::new(&bin)
                .current_dir(child_cwd(&tmp))
                .stdin(Stdio::piped())
                .stdout(Stdio::piped())
                .stderr(Stdio::null())
                .spawn()
                .unwrap_or_else(|e| panic!("spawn {}: {e}", bin.display()));
            let stdin = child.stdin.take().expect("child stdin");
            let stdout = child.stdout.take().expect("child stdout");
            let (tx, rx) = mpsc::channel();
            thread::spawn(move || {
                let mut reader = BufReader::new(stdout);
                while let Some(frame) = read_frame(&mut reader) {
                    if tx.send(frame).is_err() {
                        break;
                    }
                }
            });
            WireClient {
                stdin,
                rx,
                child,
                _tmp: tmp,
            }
        }

        pub fn send(&mut self, msg: &Value) {
            let body = serde_json::to_vec(msg).expect("serialize");
            let header = format!("Content-Length: {}\r\n\r\n", body.len());
            self.stdin
                .write_all(header.as_bytes())
                .expect("write header");
            self.stdin.write_all(&body).expect("write body");
            self.stdin.flush().expect("flush");
        }

        pub fn request(&mut self, method: &str, params: Value) -> Value {
            let id = 42;
            self.send(&json!({"jsonrpc":"2.0","id":id,"method":method,"params":params}));
            loop {
                let f = self
                    .rx
                    .recv_timeout(Duration::from_secs(30))
                    .expect("LSP read timed out — server never sent the awaited frame");
                if f.get("id").and_then(Value::as_i64) == Some(id)
                    && (f.get("result").is_some() || f.get("error").is_some())
                {
                    return f;
                }
                if f.get("method").is_some() && f.get("id").is_some() {
                    let rid = f.get("id").cloned().unwrap_or(Value::Null);
                    self.send(&json!({"jsonrpc":"2.0","id":rid,"result":null}));
                }
            }
        }

        pub fn notify(&mut self, method: &str, params: Value) {
            self.send(&json!({"jsonrpc":"2.0","method":method,"params":params}));
        }

        pub fn did_open(&mut self, uri: &str, language_id: &str, text: &str) {
            self.notify(
                "textDocument/didOpen",
                json!({"textDocument":{"uri":uri,"languageId":language_id,"version":1,"text":text}}),
            );
        }
    }

    impl Drop for WireClient {
        fn drop(&mut self) {
            let _ = self
                .stdin
                .write_all(b"Content-Length: 33\r\n\r\n{\"jsonrpc\":\"2.0\",\"method\":\"exit\"}");
            let _ = self.stdin.flush();
            let _ = self.child.kill();
            let _ = self.child.wait();
        }
    }

    fn child_cwd(tmp: &TempDir) -> &std::path::Path {
        tmp.path()
    }

    fn read_frame(reader: &mut impl BufRead) -> Option<Value> {
        let mut content_length: usize = 0;
        loop {
            let mut line = String::new();
            if reader.read_line(&mut line).ok()? == 0 {
                return None;
            }
            let line = line.trim_end();
            if line.is_empty() {
                break;
            }
            if let Some(rest) = line.to_ascii_lowercase().strip_prefix("content-length:") {
                content_length = rest.trim().parse().ok()?;
            }
        }
        let mut buf = vec![0u8; content_length];
        reader.read_exact(&mut buf).ok()?;
        serde_json::from_slice(&buf).ok()
    }
}

const G4_COMMANDS_FILE: &str = "// Code generated by ggen. DO NOT EDIT.\npub mod generated_commands {\n    pub const COMMANDS: &str = \"build\";\n}\n";
const G4_KERNEL_LIB: &str =
    "pub enum Refusal {\n    #[error(\"SBB_MUTABLE: {0}\")]\n    SbbMutable(String),\n}\n";
const G4_REFUSAL_FILE: &str = "// Code generated by ggen. DO NOT EDIT.\npub enum Refusal {\n    #[error(\"SBB_MUTABLE: {0}\")]\n    SbbMutable(String),\n}\n";

/// Lay out a ggen.toml project nested one level under a ggen.toml-free
/// workspace root. Returns (tempdir-as-workspace-root, project_root).
fn g4_project(extra: &[(&str, &str)]) -> (tempfile::TempDir, std::path::PathBuf) {
    let tmp = tempfile::tempdir().expect("tempdir");
    let proj = tmp.path().join("proj");
    std::fs::create_dir_all(&proj).expect("proj dir");
    std::fs::write(proj.join("ggen.toml"), "[project]\nname = \"g4\"\n").expect("write ggen.toml");
    for (rel, content) in extra {
        let p = tmp.path().join(rel);
        if let Some(parent) = p.parent() {
            std::fs::create_dir_all(parent).expect("parent dir");
        }
        std::fs::write(&p, content).expect("write fixture file");
    }
    (tmp, proj)
}

fn wire_initialize(client: &mut wire::WireClient, workspace_root: &std::path::Path) {
    let resp = client.request(
        "initialize",
        json!({
            "processId": null,
            "rootUri": format!("file://{}", workspace_root.display()),
            "rootPath": workspace_root.display().to_string(),
            "capabilities": {}
        }),
    );
    assert!(
        resp.get("error").is_none(),
        "initialize must not error: {resp}"
    );
    client.notify("initialized", json!({}));
}

#[test]
fn definition_fallback_resolves_generated_moniker_to_first_tree_hit() {
    let (tmp, proj) = g4_project(&[
        ("proj/src/a.rs", G4_COMMANDS_FILE),
        ("proj/src/b.rs", G4_COMMANDS_FILE),
    ]);
    let uri_a = format!("file://{}/proj/src/a.rs", tmp.path().display());

    let mut c = wire::WireClient::spawn();
    wire_initialize(&mut c, tmp.path());
    c.did_open(&uri_a, "rust", G4_COMMANDS_FILE);

    // Cursor on COMMANDS (line 2, col 16).
    let def = c.request(
        "textDocument/definition",
        json!({"textDocument":{"uri":uri_a},"position":{"line":2,"character":16}}),
    );
    assert!(
        def.get("error").is_none(),
        "definition must not error: {def}"
    );
    assert!(
        def["result"]["uri"]
            .as_str()
            .unwrap_or_default()
            .ends_with("proj/src/a.rs"),
        "definition fallback must resolve to the FIRST tree hit (a.rs sorts before b.rs), got: {def}"
    );
    assert_eq!(
        def["result"]["range"]["start"]["line"],
        json!(2),
        "COMMANDS declaration line: {def}"
    );

    // Off-symbol cursor (between the banner comment slashes) → well-formed
    // null result (no error).
    let miss = c.request(
        "textDocument/definition",
        json!({"textDocument":{"uri":uri_a},"position":{"line":0,"character":1}}),
    );
    assert!(
        miss.get("error").is_none() && miss["result"].is_null(),
        "off-symbol definition must be a well-formed null: {miss}"
    );
    let _ = proj;
}

#[test]
fn references_fallback_returns_all_tree_hits() {
    let (tmp, proj) = g4_project(&[
        ("proj/src/a.rs", G4_COMMANDS_FILE),
        ("proj/src/b.rs", G4_COMMANDS_FILE),
    ]);
    let uri_a = format!("file://{}/proj/src/a.rs", tmp.path().display());

    let mut c = wire::WireClient::spawn();
    wire_initialize(&mut c, tmp.path());
    c.did_open(&uri_a, "rust", G4_COMMANDS_FILE);

    let refs = c.request(
        "textDocument/references",
        json!({"textDocument":{"uri":uri_a},"position":{"line":2,"character":16},"context":{"includeDeclaration":true}}),
    );
    assert!(
        refs.get("error").is_none(),
        "references must not error: {refs}"
    );
    let locations = refs["result"]
        .as_array()
        .expect("references fallback must return locations");
    let uris: Vec<&str> = locations
        .iter()
        .map(|l| l["uri"].as_str().expect("location uri"))
        .collect();
    assert_eq!(
        uris.len(),
        2,
        "ALL resolve_moniker_in_tree hits (both banner files) must be returned: {uris:?}"
    );
    let ends_with_a = |u: &str| u.ends_with("proj/src/a.rs");
    let ends_with_b = |u: &str| u.ends_with("proj/src/b.rs");
    assert!(
        uris.len() == 2
            && uris.iter().any(|u| ends_with_a(u))
            && uris.iter().any(|u| ends_with_b(u)),
        "references must cover both generated files under the project root: {uris:?}"
    );
    let _ = proj;
}

#[test]
fn kernel_moniker_fallback_resolves_to_kernel_lib_rs() {
    let (tmp, proj) = g4_project(&[
        ("proj/crates/ggen-abb-sbb/src/lib.rs", G4_KERNEL_LIB),
        ("proj/src/refusal_gen.rs", G4_REFUSAL_FILE),
    ]);
    let uri_gen = format!("file://{}/proj/src/refusal_gen.rs", tmp.path().display());

    let mut c = wire::WireClient::spawn();
    wire_initialize(&mut c, tmp.path());
    c.did_open(&uri_gen, "rust", G4_REFUSAL_FILE);

    // Cursor on the SBB_MUTABLE code inside the #[error(...)] attribute
    // (line 2, inside the word).
    let def = c.request(
        "textDocument/definition",
        json!({"textDocument":{"uri":uri_gen},"position":{"line":2,"character":18}}),
    );
    assert!(
        def.get("error").is_none(),
        "definition must not error: {def}"
    );
    assert!(
        def["result"]["uri"]
            .as_str()
            .unwrap_or_default()
            .ends_with("crates/ggen-abb-sbb/src/lib.rs"),
        "two-segment kernel moniker (Refusal::SBB_MUTABLE) must resolve via \
         resolve_kernel_moniker over the kernel lib.rs, got: {def}"
    );

    let refs = c.request(
        "textDocument/references",
        json!({"textDocument":{"uri":uri_gen},"position":{"line":2,"character":18},"context":{"includeDeclaration":true}}),
    );
    assert!(
        refs.get("error").is_none(),
        "references must not error: {refs}"
    );
    let locations = refs["result"]
        .as_array()
        .expect("kernel references must return locations");
    assert!(
        !locations.is_empty()
            && locations.iter().all(|l| l["uri"]
                .as_str()
                .unwrap_or_default()
                .ends_with("crates/ggen-abb-sbb/src/lib.rs")),
        "kernel moniker references must resolve inside the kernel lib.rs: {locations:?}"
    );
}
